   675	TEST(CoherentPointDriftAccelerated, NystromCanRetryAfterTheSourceMovesCloser)
   676	{
   677	    const auto targetPoints = Cloud(1200, 81), sourcePoints = Cloud(1000, 82);
   678	    const Soa target(targetPoints), moved(sourcePoints), separated(Shifted(sourcePoints, {1000.0f, 0.0f, 0.0f}));
   679	    constexpr double logOutlier = -std::numeric_limits<double>::infinity();
   680	    E::Evaluator dense;
   681	    dense.SetTarget(target.View());
   682	    E::Sums exact;
   683	    ASSERT_TRUE(dense.Evaluate(moved.View(), 4.0, logOutlier, {.Policy = CPD::EStepPolicy::Dense}, exact));
   684	    for (const auto schedule : {Schedule::Mixed, Schedule::Fixed, Schedule::Resampled})
   685	    {
   686	        SCOPED_TRACE(int(schedule));
   687	        auto settings = Variant(Source::Points, schedule, Pattern::Random);
   688	        settings.NystromErrorLimit = 1e-3;
   689	        E::Evaluator reused, fresh;
   690	        reused.SetTarget(target.View());
   691	        fresh.SetTarget(target.View());
   692	        E::Sums rejected, recovered, control;
   693	        // At this separation all cross-kernel terms underflow; the shifted exact path still works.
   694	        ASSERT_TRUE(reused.Evaluate(separated.View(), 8.0, logOutlier, settings, rejected));
   695	        ASSERT_NE(rejected.Used, CPD::EStepPolicy::Nystrom);
   696	        ASSERT_FALSE(Landmarks(reused).empty()) << "the first approximation must actually be attempted";
   697	        ASSERT_TRUE(fresh.Evaluate(moved.View(), 4.0, logOutlier, settings, control));
   698	        ASSERT_EQ(control.Used, CPD::EStepPolicy::Nystrom);
   699	        ASSERT_TRUE(reused.Evaluate(moved.View(), 4.0, logOutlier, settings, recovered));
   700	        ASSERT_EQ(recovered.Used, CPD::EStepPolicy::Nystrom);
   701	        EXPECT_LT(recovered.SampledError, settings.NystromErrorLimit / 10.0);
   702	        for (std::size_t i = 0; i < exact.P1.size(); ++i)
   703	        {
   704	            EXPECT_NEAR(recovered.P1[i], exact.P1[i], 1e-3);
   705	            EXPECT_NEAR(recovered.PXx[i], exact.PXx[i], 1e-3);
   706	            EXPECT_NEAR(recovered.PXy[i], exact.PXy[i], 1e-3);
   707	            EXPECT_NEAR(recovered.PXz[i], exact.PXz[i], 1e-3);
   708	        }

 234	TEST(CoherentPointDriftAccelerated, NystromSampledErrorTracksTheActualExpectationError)
 235	{
 236	    // Large enough that 48 landmarks cost well below the dense rows (small inputs run exactly).
 237	    const auto targetPoints = Cloud(1200, 81);
 238	    const auto movedPoints = Rigid(Cloud(1000, 82), 0.2, {0.1, 0.0, 0.05}, 0.01, 9);
 239	    const Soa target(targetPoints), moved(movedPoints);
 240	    CPD::EStep::Evaluator dense, nystrom;
 241	    dense.SetTarget(target.View());
 242	    for (const double sigma2 : {8.0, 2.0, 0.5, 0.1})
 243	    {
 244	        nystrom.SetTarget(target.View()); // no rejection memory between the kernels
 245	        CPD::EStep::Sums exact, approx;
 246	        ASSERT_TRUE(dense.Evaluate(moved.View(), sigma2, std::log(0.05), {.Policy = CPD::EStepPolicy::Dense}, exact));
 247	        ASSERT_TRUE(nystrom.Evaluate(moved.View(), sigma2, std::log(0.05),
 248	                                     {.Policy = CPD::EStepPolicy::Nystrom, .NystromLandmarks = 48u,
 249	                                      .NystromErrorLimit = 1.0}, approx));
 250	        ASSERT_EQ(approx.Used, CPD::EStepPolicy::Nystrom) << "sigma2=" << sigma2;
 251	        EXPECT_EQ(approx.ErrorBound, 0.0) << "no bound is claimed";
 252	        double pt1 = 0.0, p1 = 0.0;
 253	        for (std::size_t j = 0; j < exact.Pt1.size(); ++j) pt1 = std::max(pt1, std::abs(exact.Pt1[j] - approx.Pt1[j]));
 254	        for (std::size_t i = 0; i < exact.P1.size(); ++i)
 255	            p1 = std::max(p1, std::abs(exact.P1[i] - approx.P1[i]) / exact.P1[i]);
 256	        std::printf("sigma2 %g: sampled %.3g, max Pt1 delta %.3g, max relative P1 delta %.3g\n", sigma2,
 257	                    approx.SampledError, pt1, p1);
 258	        // Wide kernels are nearly low rank: the approximation is accurate, and the estimate from
 259	        // 64 sampled rows is within a small factor of the worst of all rows (measured: <= 3x).
 260	        if (sigma2 >= 8.0) EXPECT_LE(p1, 1e-6) << "sigma2=" << sigma2;
 261	        EXPECT_LE(p1, 10.0 * approx.SampledError + 1e-12) << "sigma2=" << sigma2;
 262	    }
 263	    // A narrow kernel misses the default limit and is evaluated exactly.
 264	    nystrom.SetTarget(target.View());
 265	    CPD::EStep::Sums exact, fallback;
 266	    ASSERT_TRUE(nystrom.Evaluate(moved.View(), 1e-4, std::log(0.05),
 267	                                 {.Policy = CPD::EStepPolicy::Nystrom, .NystromLandmarks = 48u}, fallback));
 268	    EXPECT_NE(fallback.Used, CPD::EStepPolicy::Nystrom);
 269	    EXPECT_EQ(fallback.SampledError, 0.0);
 270	    ASSERT_TRUE(dense.Evaluate(moved.View(), 1e-4, std::log(0.05), {.Policy = fallback.Used}, exact));
 271	    EXPECT_EQ(exact.LogDenominatorSum, fallback.LogDenominatorSum);
 272	    EXPECT_EQ(exact.P1, fallback.P1);
 273	}
