1020	TEST(CoherentPointDriftAccelerated, BoxLandmarksAreUniformOverTheUnionOfTheBoxes)
1021	{
1022	    // 100 draws (seeds 0-99, a fresh evaluator each, so no rejection memory repeats a draw) of
1023	    // 48 landmarks: the shares in A only, B only and A and B match the volume shares of the union
1024	    // (binomial sd about 0.007 at 4800 samples; tolerance 0.03).
1025	    const auto targetPoints = Cloud(1200, 81);
1026	    const auto sourcePoints = Shifted(Cloud(1000, 82), {2.0f, 0.5f, 0.0f});
1027	    const Soa target(targetPoints), moved(sourcePoints);
1028	    const double sigma2 = 0.5, pad = std::sqrt(sigma2);
1029	    const auto box = [&](const std::vector<glm::vec3>& points) {
1030	        glm::dvec3 lo(1e300), hi(-1e300);
1031	        for (const auto& q : points) { lo = glm::min(lo, glm::dvec3(q)); hi = glm::max(hi, glm::dvec3(q)); }
1032	        return std::pair{lo - pad, hi + pad};
1033	    };
1034	    const auto [aLo, aHi] = box(targetPoints);
1035	    const auto [bLo, bHi] = box(sourcePoints);
1036	    const auto volume = [](glm::dvec3 lo, glm::dvec3 hi) {
1037	        const glm::dvec3 e = glm::max(hi - lo, glm::dvec3(0.0));
1038	        return e.x * e.y * e.z;
1039	    };
1040	    const double va = volume(aLo, aHi), vb = volume(bLo, bHi), vab = volume(glm::max(aLo, bLo), glm::min(aHi, bHi));
1041	    const double vu = va + vb - vab;
1042	    ASSERT_GT(vab, 0.05 * vu) << "the boxes must overlap for this test";
1043	    const auto inside = [](const glm::dvec3& p, glm::dvec3 lo, glm::dvec3 hi) {
1044	        return glm::all(glm::greaterThanEqual(p, lo)) && glm::all(glm::lessThanEqual(p, hi));
1045	    };
1046	    for (const auto pattern : {Pattern::Random, Pattern::Halton})
1047	    {
1048	        double onlyA = 0.0, onlyB = 0.0, both = 0.0, total = 0.0;
1049	        for (int draw = 0; draw < 100; ++draw)
1050	        {
1051	            auto settings = Variant(Source::BoundingBox, Schedule::Mixed, pattern);
1052	            settings.NystromErrorLimit = 1e300;
1053	            settings.NystromSampling.Seed = std::uint64_t(draw);
1054	            E::Evaluator evaluator;
1055	            evaluator.SetTarget(target.View());
1056	            E::Sums sums;
1057	            ASSERT_TRUE(evaluator.Evaluate(moved.View(), sigma2, std::log(0.05), settings, sums)) << draw;
1058	            for (const auto& p : Landmarks(evaluator))
1059	            {
1060	                const bool a = inside(p, aLo, aHi), b = inside(p, bLo, bHi);
1061	                ASSERT_TRUE(a || b);
1062	                onlyA += a && !b;
1063	                onlyB += b && !a;
1064	                both += a && b;
1065	                total += 1.0;
1066	            }
1067	        }
1068	        ASSERT_GE(total, 4000.0) << int(pattern);
1069	        EXPECT_NEAR(onlyA / total, (va - vab) / vu, 0.03) << int(pattern);
1070	        EXPECT_NEAR(onlyB / total, (vb - vab) / vu, 0.03) << int(pattern);
1071	        EXPECT_NEAR(both / total, vab / vu, 0.03) << int(pattern);
1072	    }
